#include <iostream>
#include <map>
#include <vector>
#include <algorithm>

int main() {
    // Sample data: vector of pairs
    std::vector<std::pair<int, std::string>> data = {
        {3, "three"}, {1, "one"}, {2, "two"}
    };

    // Construct a multimap from range with default comparison (std::less<int>)
    std::multimap<int, std::string> mmap_range(data.begin(), data.end());

    // Construct a multimap with custom comparison (greater than)
    std::multimap<int, std::string, std::greater<int>> mmap_custom(data.begin(), data.end());

    // Output the contents of the default multimap
    std::cout << "Default multimap (ascending order):" << std::endl;
    for (const auto& pair : mmap_range) {
        std::cout << pair.first << ": " << pair.second << std::endl;
    }

    // Output the contents of the custom multimap
    std::cout << "Custom multimap (descending order):" << std::endl;
    for (const auto& pair : mmap_custom) {
        std::cout << pair.first << ": " << pair.second << std::endl;
    }

    return 0;
}
